{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "weaken",
  "supportive_card_ids": ["C18", "C28", "C08", "C05", "C03", "C06", "C07", "C13", "C11", "C19", "C29", "C31", "C34"],
  "contradictory_card_ids": ["C45", "C47"],
  "prediction_basis_card_ids": ["C18", "C28", "C08", "C05", "C03", "C06", "C07", "C13", "C11", "C19"],
  "claims": [
    {
      "claim": "Direct nucleoside gold records provide measured oral bioavailability at or above 20% for multiple nucleoside analogs: emtricitabine 92% (C18, C28), stavudine 61-78% (C08), zidovudine 61% (C05), and didanosine 22-35% across doses and formulations (C03, C06, C07, C13, C11, C19). These are the most endpoint-direct evidence and support F >= 20% for the query as a polar ribonucleoside analog.",
      "card_ids": ["C18", "C28", "C08", "C05", "C03", "C06", "C07", "C13", "C11", "C19"]
    },
    {
      "claim": "L4 shows low Caco-2 permeability for the close analogs ribavirin and levovirin (C45, C47) together with high solubility (C43, C49, C51), but C47 explicitly notes that low Caco-2 permeability may reflect limited hCNT2 expression, so the assay does not affirmatively establish F < 20% in vivo.",
      "card_ids": ["C45", "C47", "C43", "C49", "C51"]
    },
    {
      "claim": "No L4 card provides an affirmative F < 20% outcome for the query or its exact scaffold; low permeability for close analogs is an absorption concern but is not a direct systemic-bioavailability measurement and does not overturn the direct nucleoside F records.",
      "card_ids": ["C45", "C47", "C43", "C49", "C51"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C45", "C47", "C43", "C49", "C51"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule or its exact 5-hydroxyimidazole-4-carboxamide riboside scaffold.",
    "No permeability or nucleoside-transporter data exist for the query itself; L4 data are for ribavirin/levovirin and other analogs, not the query.",
    "Caco-2 permeability may underrepresent in vivo transporter-mediated absorption (C47), so low Papp is not equivalent to low F.",
    "No first-pass metabolism, clearance, or formulation data are available for the query.",
    "It is unknown whether the ionized 5-hydroxy group (neutral fraction 0.04) impairs recognition by intestinal nucleoside transporters."
  ],
  "decision_summary": "L4 intestinal permeability data for ribavirin/levovirin are a relevant absorption concern and lower confidence, but they are indirect and carry a transporter-expression caveat; the most endpoint-direct evidence remains measured F >= 20% for multiple nucleoside analogs. Prediction remains high with low confidence."
}

